package day320

// SmallestWindowEveryDistinctLength finds the length of the smallest window
// that contains every distinct character in the input string.
// Characters may appear more than once in the window.
// Returns 0 for an empty string.
// Runtime: O(N) time, O(k) space where k is the number of distinct characters.
func SmallestWindowEveryDistinctLength(str string) int {
	if len(str) == 0 {
		return 0
	}

	// Find all distinct characters in the string
	distinctChars := make(map[rune]bool)
	for _, ch := range str {
		distinctChars[ch] = true
	}

	totalDistinct := len(distinctChars)

	// If there's only one distinct character or the string has only one char
	if totalDistinct <= 1 {
		return totalDistinct
	}

	// Sliding window approach
	windowCounts := make(map[rune]int)
	formed := 0 // Number of distinct characters in current window with required count

	left := 0
	minLen := len(str) + 1

	for right := 0; right < len(str); right++ {
		// Convert byte to rune for proper Unicode handling
		rightChar := rune(str[right])

		// Add the right character to the window
		windowCounts[rightChar]++

		// If this character's count just became 1 (it was 0 before), we have a new distinct char
		if windowCounts[rightChar] == 1 {
			formed++
		}

		// Try to contract the window from the left while it still contains all distinct chars
		for formed == totalDistinct && left <= right {
			// Update minimum length if current window is smaller
			currentLen := right - left + 1
			if currentLen < minLen {
				minLen = currentLen
			}

			// Remove the left character from the window
			leftChar := rune(str[left])
			windowCounts[leftChar]--

			// If this character's count becomes 0, we lost a distinct character
			if windowCounts[leftChar] == 0 {
				formed--
			}

			left++
		}
	}

	if minLen > len(str) {
		return 0
	}

	return minLen
}
EOF

