package main

import (
	"fmt"
)

func main() {
	str := "jiujitsu"

	// Find distinct characters
	distinct := make(map[rune]bool)
	for _, ch := range str {
		distinct[ch] = true
	}

	fmt.Printf("String: %s\n", str)
	fmt.Printf("Distinct characters: ")
	for ch := range distinct {
		fmt.Printf("%c ", ch)
	}
	fmt.Printf("\nNumber of distinct characters: %d\n", len(distinct))

	// The last 5 characters are "jitsu"
	window := str[len(str)-5:]
	fmt.Printf("\nLast 5 characters: %s\n", window)

	// Check if they contain all distinct chars
	windowChars := make(map[rune]bool)
	for _, ch := range window {
		windowChars[ch] = true
	}

	fmt.Printf("Characters in window: ")
	for ch := range windowChars {
		fmt.Printf("%c ", ch)
	}
	fmt.Printf("\nAll distinct chars in window: %v\n", len(windowChars) == len(distinct))
}
